 t.MapPut("/events/{id:guid}",async(Guid tenant,Guid id,EventWrite r,AppDb db,Access a,CommunityService s)=>{await using var tx=await db.Database.BeginTransactionAsync();await Lock(db,tenant,id);var e=await db.Set<CommunityEvent>().SingleOrDefaultAsync(e=>e.TenantId==tenant&&e.Id==id)??throw new AccessDeniedException();await a.Require(tenant,"events.manage",e.UnitId);await a.Require(tenant,"events.manage",r.UnitId);if(e.Revision!=r.Revision)return Results.Conflict();if(e.Status=="Cancelled")throw new DomainException("Cancelled events remain historical");if(await db.Set<EventRegistration>().AnyAsync(x=>x.EventId==id&&x.Status!="Cancelled")){if(r.Capacity<await db.Set<EventRegistration>().Where(x=>x.EventId==id&&x.Status=="Confirmed").SumAsync(x=>x.Companions+1))throw new DomainException("Capacity cannot fall below confirmed seats");if(e.UnitId!=r.UnitId||e.StartsAt!=r.StartsAt.ToUniversalTime()||e.Visibility!=r.Visibility||!e.Audience.Order().SequenceEqual((r.Visibility=="Chapter"&&r.UnitId!=null?new[]{r.UnitId.Value}:r.Audience??[]).Order()))throw new DomainException("An event with registrations cannot change its ownership, date or audience; cancel and duplicate it");}await Apply(e,r,db,a,s);e.Revision++;s.Version(tenant,id,"Event",e.Revision,e);await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(e);});
 t.MapPost("/events/{id:guid}/decision",async(Guid tenant,Guid id,CommunityReview r,AppDb db,Access a,CommunityService s)=>{await using var tx=await db.Database.BeginTransactionAsync();await Lock(db,tenant,id);var e=await db.Set<CommunityEvent>().SingleOrDefaultAsync(e=>e.TenantId==tenant&&e.Id==id)??throw new AccessDeniedException();if(e.Revision!=r.Revision)return Results.Conflict();if(e.Status!="Pending Approval")throw new DomainException("Event is not awaiting review");await s.Decision(tenant,id,e.AuthorId,e.UnitId,"Event",e.Stages,e.Stage,r);if(r.Decision=="Approve"){e.Stage++;if(e.Stage==CommunityService.Stages(e.Stages).Length){e.Status=CommunityService.Ready(e.ScheduledAt);if(e.Status=="Published")e.PublishedAt=DateTimeOffset.UtcNow;}}else e.Status=r.Decision=="Reject"?"Rejected":"Changes Requested";e.Revision++;await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(e);});
