 var output=new List<object>();var skipped=0;await using var tx=await db.Database.BeginTransactionAsync();await Lock(db,tenant,id);foreach(var group in recipients.GroupBy(x=>x.email.ToLowerInvariant())){var recipient=group.First();if(group.Any(x=>!CommunityService.CommunicationAllowed(x.profile))){skipped++;continue;}if(await db.Set<EventInvitation>().AnyAsync(i=>i.TenantId==tenant&&i.EventId==id&&i.Email==recipient.email)){skipped++;continue;}var token=CommunityService.Token();var invite=new EventInvitation{TenantId=tenant,EventId=id,SenderId=a.UserId,UserId=recipient.user,MembershipId=recipient.member,Email=recipient.email,Name=recipient.name,TokenHash=CommunityService.Hash(token),ExpiresAt=DateTimeOffset.UtcNow.AddDays(r.Days),Status=r.Channel=="Email"?"Queued":"In App"};db.Add(invite);var url=$"/app/community/events/{id}?tenant={tenant}&invitation={token}";if(r.Channel=="Email")db.Outbox.Add(new(){Recipient=recipient.email,Subject="Event invitation: "+e.Title,Body="Sign in with this verified recipient email to respond: "+(configuration["PublicUrl"]??"http://127.0.0.1:5088").TrimEnd('/')+url});output.Add(new{invite.Id,url,invite.Status});}a.Audit(tenant,"event.invitations.created",id,new{count=output.Count,skipped,r.Channel});await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(new{items=output,skipped,delivery=r.Channel=="Email"?"Queued to existing outbox; provider delivery is not asserted":"Available in app"});});
