 t.MapPut("/events/{id:guid}/rsvp",async(Guid tenant,Guid id,ReactionWrite r,AppDb db,Access a,CommunityService s)=>{var e=await s.Event(tenant,id);if(e.Status!="Published"||DateTimeOffset.UtcNow>e.RegistrationCloses)throw new DomainException("Responses are closed");await s.Eligibility(e,a.UserId);if(!new[]{"Going","Maybe","Not Going","No Response"}.Contains(r.Kind))throw new DomainException("Unknown response");await db.Database.ExecuteSqlInterpolatedAsync($"INSERT INTO \"EventRsvp\" (\"Id\",\"TenantId\",\"EventId\",\"UserId\",\"Response\",\"At\") VALUES ({Guid.NewGuid()},{tenant},{id},{a.UserId},{r.Kind},{DateTimeOffset.UtcNow}) ON CONFLICT (\"TenantId\",\"EventId\",\"UserId\") DO UPDATE SET \"Response\"=EXCLUDED.\"Response\",\"At\"=EXCLUDED.\"At\"");a.Audit(tenant,"event.rsvp.changed",id,new{response=r.Kind});await db.SaveChangesAsync();return Results.NoContent();});
