 t.MapPost("/events/{id:guid}/registrations/{registration:guid}/decision",async(Guid tenant,Guid id,Guid registration,CommunityReview r,AppDb db,Access a,CommunityService s)=>{await using var tx=await db.Database.BeginTransactionAsync();await Lock(db,tenant,id);var e=await s.Event(tenant,id);var reg=await db.Set<EventRegistration>().SingleOrDefaultAsync(x=>x.TenantId==tenant&&x.EventId==id&&x.Id==registration)??throw new AccessDeniedException();var manage=await a.Can(tenant,"events.manage",e.UnitId);if(!manage&&(reg.UserId!=a.UserId||r.Decision!="Cancel"))throw new AccessDeniedException();if(reg.Revision!=r.Revision)return Results.Conflict();if(r.Decision=="Approve"){if(reg.UserId==a.UserId||reg.Status!="Awaiting Approval"||e.Status!="Published")throw new DomainException("Registration cannot be approved");await s.Eligibility(e,reg.UserId);var occupied=await db.Set<EventRegistration>().Where(x=>x.TenantId==tenant&&x.EventId==id&&x.Status=="Confirmed").SumAsync(x=>x.Companions+1);reg.Status=occupied+reg.Companions+1<=e.Capacity?"Confirmed":"Waitlisted";}else if(r.Decision=="Cancel"||r.Decision=="Reject"&&manage){reg.Status=r.Decision=="Cancel"?"Cancelled":"Rejected";await db.Set<EventPass>().Where(p=>p.TenantId==tenant&&p.RegistrationId==reg.Id&&p.RevokedAt==null).ExecuteUpdateAsync(x=>x.SetProperty(p=>p.RevokedAt,DateTimeOffset.UtcNow));}else throw new DomainException("Unknown registration decision");reg.Revision++;a.Audit(tenant,"event.registration."+r.Decision.ToLower(),reg.Id,new{r.Note});await db.SaveChangesAsync();if(e.Status=="Published"&&DateTimeOffset.UtcNow<e.RegistrationCloses){await s.Promote(e);await db.SaveChangesAsync();}await tx.CommitAsync();return Results.Ok(reg);});
