nce.Voided=false;attendance.At=DateTimeOffset.UtcNow;attendance.OperatorId=a.UserId;attendance.EntryPoint=r.EntryPoint;a.Audit(tenant,"event.checked.in",reg.Id,new{r.EntryPoint});await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(new{state="Valid",registration=reg.Id,name=reg.Name,attendance.At,reg.Companions});});
