 t.MapPost("/events/{id:guid}/attendance/{attendance:guid}/correct",async(Guid tenant,Guid id,Guid attendance,ReportWrite r,AppDb db,Access a,CommunityService s)=>{var e=await s.Event(tenant,id);await a.Require(tenant,"events.manage",e.UnitId);var at=await db.Set<EventAttendance>().SingleOrDefaultAsync(x=>x.TenantId==tenant&&x.EventId==id&&x.Id==attendance)??throw new AccessDeniedException();if(string.IsNullOrWhiteSpace(r.Reason))throw new DomainException("A correction reason is required");at.Voided=true;at.Correction=r.Reason;a.Audit(tenant,"event.attendance.corrected",at.Id,new{r.Reason});await db.SaveChangesAsync();return Results.NoContent();});
 t.MapGet("/events/{id:guid}/analytics",async(Guid tenant,Guid id,AppDb db,Access a,CommunityService s)=>{var e=await s.Event(tenant,id);await a.Require(tenant,"events.analytics",e.UnitId);var registrations=db.Set<EventRegistration>().Where(r=>r.TenantId==tenant&&r.EventId==id);var attendance=db.Set<EventAttendance>().Where(at=>at.TenantId==tenant&&at.EventId==id&&!at.Voided);return Results.Ok(new{eligible=await s.Eligible(e).Select(m=>m.PersonId).Distinct().CountAsync(),invitations=await db.Set<EventInvitation>().CountAsync(i=>i.TenantId==tenant&&i.EventId==id),rsvps=await db.Set<EventRsvp>().Where(r=>r.TenantId==tenant&&r.EventId==id).GroupBy(r=>r.Response).Select(g=>new{status=g.Key,count=g.Count()}).ToListAsync(),registrations=await registrations.CountAsync(),confirmed=await registrations.CountAsync(r=>r.Status=="Confirmed"),confirmedSeats=await registrations.Where(r=>r.Status=="Confirmed").SumAsync(r=>r.Companions+1),checkedIn=await attendance.CountAsync(),attendedSeats=await attendance.SumAsync(at=>at.PeopleCount),guests=await registrations.CountAsync(r=>r.MembershipId==null),noShows=e.EndsAt<DateTimeOffset.UtcNow?(int?)await registrations.CountAsync(r=>r.Status=="Confirmed"&&!attendance.Any(at=>at.RegistrationId==r.Id)):null,byChapter=await registrations.Where(r=>r.MembershipId!=null).GroupBy(r=>db.Memberships.Where(m=>m.Id==r.MembershipId).Select(m=>m.ChapterId).First()).Select(g=>new{chapterId=g.Key,registrations=g.Count(),attendance=g.Count(r=>attendance.Any(at=>at.RegistrationId==r.Id))}).ToListAsync(),byCategory=await registrations.Where(r=>r.MembershipId!=null).GroupBy(r=>db.Memberships.Where(m=>m.Id==r.MembershipId).Select(m=>m.CategoryId).First()).Select(g=>new{categoryId=g.Key,registrations=g.Count(),attendance=g.Count(r=>attendance.Any(at=>at.RegistrationId==r.Id))}).ToListAsync()});});
