 public static Task<int> Lock(AppDb db,Guid tenant,Guid id)=>db.Database.ExecuteSqlInterpolatedAsync($"SELECT pg_advisory_xact_lock(hashtext({tenant.ToString()}),hashtext({id.ToString()}))");
 static async Task Apply(CommunityEvent e,EventWrite r,AppDb db,Access a,CommunityService s){CommunityService.EventDates(r);if(!await db.Set<ActivityCategory>().AnyAsync(c=>c.TenantId==e.TenantId&&c.Id==r.CategoryId&&c.Kind=="Event"&&c.Active))throw new DomainException("Choose an event type");var audience=await s.Audience(e.TenantId,r.UnitId,r.Visibility,r.Audience,true,"events.manage");var cohosts=r.CoHosts??[];if(await db.Units.CountAsync(u=>u.TenantId==e.TenantId&&cohosts.Contains(u.Id))!=cohosts.Distinct().Count())throw new AccessDeniedException();foreach(var id in cohosts)await a.Require(e.TenantId,"events.manage",id);if((r.MemberIds??[]).Length>1000||(r.CategoryIds??[]).Length>100||(r.CommitteeIds??[]).Length>100||(r.CoHosts??[]).Length>20)throw new DomainException("Audience selection is too large");var memberIds=r.MemberIds??[];var directory=(await new MembershipService(db,a).Directory(e.TenantId)).Select(m=>m.Id);if(await directory.CountAsync(m=>memberIds.Contains(m))!=memberIds.Distinct().Count())throw new AccessDeniedException();if(await db.MembershipCategories.CountAsync(c=>c.TenantId==e.TenantId&&(r.CategoryIds??Array.Empty<Guid>()).Contains(c.Id))!=(r.CategoryIds??[]).Distinct().Count())throw new AccessDeniedException();foreach(var committee in r.CommitteeIds??[]){var c=await db.Committees.SingleOrDefaultAsync(c=>c.TenantId==e.TenantId&&c.Id==committee&&c.Status=="Active")??throw new AccessDeniedException();await a.Require(e.TenantId,"events.manage",c.UnitId);}try{var questions=JsonNode.Parse(r.Questions)!.AsArray();if(questions.Count>20||questions.Any(q=>q==null||q["key"]==null||q["label"]==null||q["key"]!.ToString().Length>50||q["label"]!.ToString().Length>200))throw new Exception();}catch{throw new DomainException("Questions need key, label and optional required fields, up to twenty questions");}
 e.UnitId=r.UnitId;e.CategoryId=r.CategoryId;e.Title=r.Title;e.Body=CommunityService.Rich(r.Body);e.StartsAt=r.StartsAt.ToUniversalTime();e.EndsAt=r.EndsAt.ToUniversalTime();e.RegistrationOpens=r.RegistrationOpens.ToUniversalTime();e.RegistrationCloses=r.RegistrationCloses.ToUniversalTime();e.TimeZone=r.TimeZone;e.Venue=r.Venue;e.Mode=r.Mode;e.OnlineUrl=r.OnlineUrl;e.Capacity=r.Capacity;e.AllowGuests=r.AllowGuests;e.MaxCompanions=r.MaxCompanions;e.RegistrationApproval=r.RegistrationApproval;e.InvitationOnly=r.InvitationOnly;e.Visibility=r.Visibility;e.Audience=audience;e.MemberIds=memberIds;e.CategoryIds=r.CategoryIds??[];e.CommitteeIds=r.CommitteeIds??[];e.LeadersOnly=r.LeadersOnly;e.CoHosts=r.CoHosts??[];e.Questions=r.Questions;e.ScheduledAt=r.ScheduledAt?.ToUniversalTime();e.Stages=(await s.Policy(e.TenantId)).EventStages;e.Stage=0;e.Status=r.Submit?(CommunityService.Stages(e.Stages).Length==0?CommunityService.Ready(e.ScheduledAt):"Pending Approval"):"Draft";e.PublishedAt=e.Status=="Published"?DateTimeOffset.UtcNow:null;
 }
